from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            False,
            0,
            DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-200, 200, timedelta(days=0), timedelta(days=365))
        self.option_symbol = option.Symbol

        self.closes = []
        self.previous_fast = None
        self.previous_slow = None
        self.entry_signal_pending = False

        self.held_symbol = None
        self.entry_price = None
        self.expiry_date = None
        self.pre_expiry_date = None
        self.blocked_entry_date = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.equity_exit_ticket = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # With regular-hours SPY minute data, this produces bars ending 09:35,
        # 09:40, etc., aligned to New York clock boundaries.
        self.closes.append(bar.Close)
        if len(self.closes) > 20:
            self.closes.pop(0)

        if len(self.closes) < 20:
            return

        fast = sum(self.closes[-5:]) / 5.0
        slow = sum(self.closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = bar.EndTime
        eligible_time = (
            (bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45))
            and (bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30))
        )

        if bullish_cross and eligible_time:
            self.entry_signal_pending = True

    def OnData(self, slice):
        self._handle_unexpected_spy_position()

        if self.held_symbol is not None:
            if not self.Portfolio[self.held_symbol].Invested and not self._ticket_open(self.exit_ticket):
                self._clear_position_state()
            else:
                self._handle_expiration_exit()
                self._handle_profit_target(slice)

        if not self.entry_signal_pending:
            return

        # The signal is evaluated exactly once on the Slice that closed the bar.
        self.entry_signal_pending = False

        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self._ticket_open(self.entry_ticket):
            return

        contract = self._select_contract(slice)
        if contract is None:
            self.Debug(f"{self.Time}: Entry skipped; no qualifying SPY call contract.")
            return

        self.entry_ticket = self.MarketOrder(contract.Symbol, 1, tag="Bullish 5-minute MA crossover")
        self.Debug(f"{self.Time}: Submitted entry for {contract.Symbol}.")

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiry_date = order_event.Symbol.ID.Date.date()
                previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
                    order_event.Symbol.ID.Date
                )
                self.pre_expiry_date = previous_trading_day.date()
                self.entry_ticket = None
                self.Debug(
                    f"{self.Time}: Entry filled {self.held_symbol} at {self.entry_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"{self.Time}: Entry order did not fill.")
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: Exit filled for {order_event.Symbol}.")
                self.exit_ticket = None
                if self.held_symbol == order_event.Symbol and not self.Portfolio[order_event.Symbol].Invested:
                    self._clear_position_state()
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

        if self.equity_exit_ticket is not None and order_event.OrderId == self.equity_exit_ticket.OrderId:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.equity_exit_ticket = None

    def _select_contract(self, slice):
        contracts = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Symbol.ID.Underlying != self.spy:
                    continue
                if contract.Right != OptionRight.Call:
                    continue
                if (contract.Expiry.date() - self.Time.date()).days < 7:
                    continue
                contracts.append(contract)

        if not contracts:
            return None

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        minimum_strike = 1.01 * self.Securities[self.spy].Price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            return None

        return min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))

    def _handle_profit_target(self, slice):
        if self.entry_price is None or self._ticket_open(self.exit_ticket):
            return

        quote_contract = None
        for chain in slice.OptionChains.Values:
            if self.held_symbol in chain.Contracts:
                quote_contract = chain.Contracts[self.held_symbol]
                break

        if quote_contract is None:
            return

        bid = quote_contract.BidPrice
        ask = quote_contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")
            self.Debug(f"{self.Time}: Profit-target exit submitted for {self.held_symbol}.")

    def _handle_expiration_exit(self):
        if self.held_symbol is None or self.expiry_date is None:
            return

        # On expiration day, exit immediately and prohibit a replacement entry.
        if self.Time.date() >= self.expiry_date:
            self.blocked_entry_date = self.Time.date()
            if not self._ticket_open(self.exit_ticket):
                self._submit_exit("Expiration-day protection")
                self.Debug(f"{self.Time}: Expiration protection exit submitted for {self.held_symbol}.")
            return

        if (
            self.Time.date() == self.pre_expiry_date
            and self.Time.hour == 15
            and self.Time.minute == 45
            and not self._ticket_open(self.exit_ticket)
        ):
            self._submit_exit("Pre-expiration 15:45 exit")
            self.Debug(f"{self.Time}: Pre-expiration exit submitted for {self.held_symbol}.")

    def _submit_exit(self, reason):
        self._cancel_open_exit_orders()

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity, tag=reason)

    def _cancel_open_exit_orders(self):
        if self._ticket_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing with required market exit")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0 and not self._ticket_open(self.equity_exit_ticket):
            self.Debug(f"{self.Time}: Unexpected SPY exercise/assignment position; liquidating.")
            self.equity_exit_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise/assignment liquidation"
            )

    @staticmethod
    def _ticket_open(ticket):
        return ticket is not None and ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def _clear_position_state(self):
        self.held_symbol = None
        self.entry_price = None
        self.expiry_date = None
        self.pre_expiry_date = None
        self.exit_ticket = None
