            self.pending_signal_bar = None
            self.TryEnter(data, signal_bar)

        self.ProcessExpiration(data)
        self.ProcessExits(data)

    def OnFiveMinuteBar(self, sender, bar):
        self.closes.append(float(bar.Close))

        if len(self.closes) < 20:
