        if not self.Portfolio[self.spy].Invested:
            return

        if self.HasOpenEquityLiquidationOrder():
            return

        quantity = self.Portfolio[self.spy].Quantity
        self.equity_liquidation_order_id = self.MarketOrder(self.spy, -quantity).OrderId
        self.Debug(
            f"{self.Time}: Unexpected SPY equity position detected "
            f"(exercise/assignment); liquidation submitted."
        )

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id and order_event.FillQuantity > 0:
            self.entry_price = float(order_event.FillPrice)
            self.Debug(
                f"{self.Time}: Entry filled: {self.held_contract} "
                f"at {self.entry_price:.2f}."
            )

        if order_event.OrderId == self.exit_order_id and order_event.Status == OrderStatus.Filled:
            self.Debug(f"{self.Time}: Exit filled: {self.held_contract} at {order_event.FillPrice:.2f}.")
            self.held_contract = None
            self.entry_price = None
            self.entry_order_id = None
            self.exit_order_id = None

        if (
            order_event.OrderId == self.equity_liquidation_order_id
            and order_event.Status == OrderStatus.Filled
        ):
            self.equity_liquidation_order_id = None

    def HasOpenEntryOrder(self):
        return self.IsOrderOpen(self.entry_order_id)

    def HasOpenExitOrder(self):
        return self.IsOrderOpen(self.exit_order_id)

    def HasOpenEquityLiquidationOrder(self):
        return self.IsOrderOpen(self.equity_liquidation_order_id)

    def IsOrderOpen(self, order_id):
        if order_id is None:
            return False

        order = self.Transactions.GetOrderById(order_id)
        if order is None:
            return False

        return order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted,
            OrderStatus.CancelPending
        )
