from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute, Market.USA, False).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(timedelta(0), timedelta(90))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.interval_start = None
        self.interval_closes = {}

        self.held_contract = None
        self.entry_fill_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.block_entries_on = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.CheckTimeStop
        )

    def OnData(self, data: Slice):
        self.HandleUnexpectedEquityPosition()

        if self.held_contract is not None and self.Time.date() >= self.held_contract.ID.Date.date():
            self.block_entries_on = self.Time.date()
            self.Debug(f"Expiration safety exit requested for {self.held_contract}")
            self.SubmitExit("expiration safety exit")

        self.CheckProfitTarget(data)
        self.BuildFiveMinuteBar(data)

    def BuildFiveMinuteBar(self, data: Slice):
        if self.spy not in data.Bars:
            return

        minute_bar = data.Bars[self.spy]
        bar_time = minute_bar.Time
        interval_start = bar_time.replace(
            minute=(bar_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.interval_start is None or interval_start != self.interval_start:
            self.interval_start = interval_start
            self.interval_closes = {}

        self.interval_closes[bar_time] = minute_bar.Close

        interval_end = interval_start + timedelta(minutes=5)
        if minute_bar.EndTime != interval_end:
            return

        expected_times = [interval_start + timedelta(minutes=i) for i in range(5)]
        if all(t in self.interval_closes for t in expected_times):
            self.OnFiveMinuteBar(interval_end, self.interval_closes[expected_times[-1]], data)

        self.interval_start = None
        self.interval_closes = {}

    def OnFiveMinuteBar(self, end_time, close, data: Slice):
        self.fast.Update(end_time, close)
        self.slow.Update(end_time, close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        crossed_up = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        eligible_time = (
            (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
            and (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
        )

        if (
            crossed_up
            and eligible_time
            and self.block_entries_on != self.Time.date()
            and not self.HasOptionPosition()
            and not self.OrderIsOpen(self.entry_ticket)
            and not self.OrderIsOpen(self.exit_ticket)
        ):
            self.EnterCall(data)

    def EnterCall(self, data: Slice):
        if self.spy not in data.Bars:
            self.Debug("Skipped entry: no current SPY bar.")
            return

        spy_price = data.Bars[self.spy].Close
        today = self.Time.date()

        contracts = []
        for chain in data.OptionChains.Values:
            contracts.extend(chain)

        if not contracts:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        valid_expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if (contract.Expiry.date() - today).days >= 7
        })

        if not valid_expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        expiration = valid_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no call at {expiration} with strike >= {minimum_strike:.2f}."
            )
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def CheckProfitTarget(self, data: Slice):
        if not self.HasOptionPosition() or self.entry_fill_price is None:
            return

        if self.held_contract not in data.QuoteBars:
            return

        quote = data.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit(f"profit target reached at midpoint {midpoint:.2f}")

    def CheckTimeStop(self):
        if not self.HasOptionPosition():
            return

        expiry_date = self.held_contract.ID.Date.date()
        previous_trading_day = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(previous_trading_day, datetime.min.time())
        ):
            previous_trading_day -= timedelta(days=1)

        if self.Time.date() == previous_trading_day:
            self.SubmitExit("15:45 pre-expiration time stop")

    def SubmitExit(self, reason):
